/* Normalized Apple ADT RO survey contract, independent of the standalone FDT ABI. */
#pragma once
#include <stdint.h>
#include <stddef.h>
struct zwifi_region {uint64_t physical,bytes;};
struct zwifi_contract {uint8_t magic[8];uint32_t version,bytes;struct zwifi_region region[4];uint32_t local_pid,remote_pid,local_item,remote_item,crash_item,qmp_client,qmp_signal,wpss_client,glink_signal,smp2p_signal;uint8_t source_digest[32];uint32_t flags,crc;};
_Static_assert(sizeof(struct zwifi_contract)==160,"Normalized ADT contract size");
#define ZWIFI_ADT_FACTS 63u
static const uint8_t zwifi_contract_bytes[160]={0x5a,0x49,0x57,0x50,0x52,0x4f,0x30,0x31,0x1,0x0,0x0,0x0,0xa0,0x0,0x0,0x0,0x0,0x0,0x90,0x80,0x0,0x0,0x0,0x0,0x0,0x0,0x20,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x86,0x80,0x0,0x0,0x0,0x0,0x0,0x0,0x2,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x30,0xc,0x0,0x0,0x0,0x0,0x0,0x4,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x80,0xd1,0xe,0x0,0x0,0x0,0x0,0x0,0x10,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0xd,0x0,0x0,0x0,0x68,0x2,0x0,0x0,0x69,0x2,0x0,0x0,0x72,0x2,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x18,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x2,0x0,0x0,0x0,0x13,0x15,0x1,0x95,0x81,0x8f,0xde,0xee,0xaa,0xf8,0xa7,0xe2,0x5b,0x8d,0x3e,0xd0,0xbc,0x63,0x53,0xf8,0xbe,0xe3,0x4d,0xa4,0x65,0x4e,0x2b,0xe,0x76,0xc2,0x7e,0xa7,0x1,0x0,0x0,0x0,0x95,0xfb,0xe0,0x4b};
static uint32_t zwifi_crc32(const void*data,size_t bytes){const uint8_t*p=data;uint32_t c=~0u;for(size_t i=0;i<bytes;i++){c^=p[i];for(unsigned b=0;b<8;b++)c=(c>>1)^(0xedb88320u&(0u-(c&1)));}return~c;}
static int zwifi_contract_valid(const struct zwifi_contract*c){if(!c)return 0;const uint8_t*p=(const uint8_t*)c;for(unsigned i=0;i<160;i++)if(p[i]!=zwifi_contract_bytes[i])return 0;struct zwifi_contract copy=*c;copy.crc=0;return zwifi_crc32(&copy,160)==c->crc;}
